import React from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip as RechartsTooltip, 
  ResponsiveContainer, 
  Cell,
  LineChart,
  Line
} from 'recharts';
import { 
  Download, 
  TrendingUp, 
  Calendar, 
  PieChart as PieChartIcon,
  ChevronRight,
  TrendingDown,
  Activity
} from 'lucide-react';
import { DayData } from '../types';

interface ReportsProps {
  calendarData: DayData[];
  onExport: () => void;
}

const Reports: React.FC<ReportsProps> = ({ calendarData, onExport }) => {
  const completedDays = calendarData.filter(d => d.completed);
  const last7Days = completedDays.slice(-7);

  const chartData = last7Days.map(d => ({
    name: `Day ${d.day}`,
    completion: Math.round((d.tasks.filter(t => t.completed).length / d.tasks.length) * 100),
    points: d.points
  }));

  const categoryBreakdown = [
    { name: 'Morning', color: '#60a5fa', key: 'Morning Routine' },
    { name: 'English', color: '#a78bfa', key: 'English Learning' },
    { name: 'Trading', color: '#34d399', key: 'Trading' },
    { name: 'Coding', color: '#f472b6', key: 'Coding/DSA' },
    { name: 'Dev', color: '#fb923c', key: 'Flutter/React' }
  ].map(cat => {
    const total = completedDays.reduce((acc, day) => acc + day.tasks.filter(t => t.category === cat.key).length, 0);
    const completed = completedDays.reduce((acc, day) => acc + day.tasks.filter(t => t.category === cat.key && t.completed).length, 0);
    return { ...cat, percentage: total > 0 ? Math.round((completed / total) * 100) : 0 };
  });

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-fade-in">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="space-y-1">
          <h2 className="text-sm font-bold tracking-widest text-emerald-400 uppercase">Performance Reports</h2>
          <h1 className="text-4xl font-bold tracking-tight">Analytics & Stats</h1>
          <p className="text-slate-400 font-medium">Detailed breakdown of your consistency and growth.</p>
        </div>

        <button 
          onClick={onExport}
          className="flex items-center gap-2 px-6 py-3 bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 transition-all font-bold text-sm shadow-xl"
        >
          <Download size={18} /> EXPORT DATA
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left: Charts */}
        <div className="lg:col-span-2 space-y-8">
          <div className="glass-card p-6 min-h-[400px]">
            <div className="flex items-center justify-between mb-8">
               <h3 className="text-lg font-bold flex items-center gap-2">
                 <TrendingUp size={20} className="text-blue-400" />
                 Weekly Performance (%)
               </h3>
            </div>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#ffffff05" vertical={false} />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} stroke="#94a3b8" fontSize={10} tickMargin={10} />
                  <YAxis domain={[0, 100]} axisLine={false} tickLine={false} stroke="#94a3b8" fontSize={10} tickMargin={10} />
                  <RechartsTooltip 
                    contentStyle={{ borderRadius: '16px', background: '#020617ef', border: '1px solid #ffffff10', backdropFilter: 'blur(10px)' }}
                    itemStyle={{ color: '#60a5fa', fontWeight: 'bold' }}
                    labelStyle={{ color: '#fff', marginBottom: '8px' }}
                  />
                  <Bar dataKey="completion" radius={[6, 6, 0, 0]} barSize={24}>
                    {chartData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.completion >= 80 ? '#60a5fa' : '#ef4444'} fillOpacity={0.8} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="glass-card p-6">
               <h3 className="text-lg font-bold mb-6 flex items-center gap-2">
                 <Activity size={20} className="text-purple-400" />
                 Category Proficiency
               </h3>
               <div className="space-y-5">
                  {categoryBreakdown.map((cat, i) => (
                    <div key={i} className="space-y-2">
                      <div className="flex justify-between text-xs font-bold uppercase tracking-widest text-slate-400">
                        <span>{cat.name}</span>
                        <span>{cat.percentage}%</span>
                      </div>
                      <div className="w-full bg-white/5 h-2 rounded-full overflow-hidden">
                        <div 
                          className="h-full rounded-full transition-all duration-1000"
                          style={{ width: `${cat.percentage}%`, background: cat.color }}
                        />
                      </div>
                    </div>
                  ))}
               </div>
            </div>

            <div className="glass-card p-6 bg-gradient-to-br from-indigo-600/10 to-transparent">
               <h3 className="text-lg font-bold mb-6 flex items-center gap-2">
                 <Calendar size={20} className="text-indigo-400" />
                 Consistency Heatmap
               </h3>
               {/* Simplified heatmap grid */}
               <div className="grid grid-cols-7 gap-2">
                  {Array.from({length: 49}).map((_, i) => (
                    <div 
                      key={i} 
                      className={`aspect-square rounded-sm ${
                        i < completedDays.length 
                          ? (completedDays[i]?.grade === 'A+' ? 'bg-emerald-500 shadow-[0_0_8px_#10b98166]' : 'bg-emerald-500/40')
                          : 'bg-white/5'
                      }`}
                    />
                  ))}
               </div>
               <p className="mt-4 text-[10px] text-slate-500 uppercase tracking-widest font-bold">LATEST 7 WEEKS ACTIVITY</p>
            </div>
          </div>
        </div>

        {/* Right: Summary Insights */}
        <div className="space-y-8">
           <div className="glass-card p-6 bg-blue-600/5 group">
              <h4 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-4">Core Analytics</h4>
              <div className="space-y-6">
                {[
                  { label: "Overall Completion", value: "84%", trend: "+12%", up: true },
                  { label: "Longest Streak", value: "14 Days", trend: "0.2 Avg", up: true },
                  { label: "Trading Success", value: "92%", trend: "+5%", up: true },
                  { label: "Late Reviews", value: "3", trend: "-2", up: false }
                ].map((stat, i) => (
                  <div key={i} className="flex items-center justify-between">
                    <div>
                      <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-0.5">{stat.label}</p>
                      <p className="text-xl font-bold text-white">{stat.value}</p>
                    </div>
                    <div className={`flex items-center text-[10px] font-bold px-2 py-0.5 rounded-full ${stat.up ? 'bg-emerald-500/10 text-emerald-400' : 'bg-red-500/10 text-red-400'}`}>
                      {stat.trend} {stat.up ? <TrendingUp size={10} className="ml-1" /> : <TrendingDown size={10} className="ml-1" />}
                    </div>
                  </div>
                ))}
              </div>
           </div>

           <div className="glass-card p-6 border-white/5">
              <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-6 px-1">Daily Breakdown</h4>
              <div className="space-y-2 max-h-[400px] overflow-y-auto scrollbar-thin pr-2">
                 {completedDays.slice().reverse().map((day, i) => (
                   <div key={i} className="glass border-white/5 p-4 rounded-2xl flex items-center justify-between group hover:border-blue-500/30 transition-all cursor-pointer">
                      <div className="flex items-center gap-4">
                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-xs ${
                          day.grade === 'A+' ? 'bg-emerald-500 text-white' : 'bg-white/5 text-slate-400 group-hover:text-white'
                        }`}>
                          {day.grade}
                        </div>
                        <div>
                          <p className="text-xs font-bold text-white uppercase tracking-tighter">Day {day.day}</p>
                          <p className="text-[10px] text-slate-500">{new Date(day.date).toDateString()}</p>
                        </div>
                      </div>
                      <ChevronRight size={14} className="text-slate-600 transition-transform group-hover:translate-x-1" />
                   </div>
                 ))}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default Reports;
